(function (root) {
  root.MADO_SPOT_PAGE_DATA = {"id":"tamaruya-wasabi-sign","lang":"ja","readingLayout":{"version":1,"compactGuide":true,"visibility":{"label":"見える時間の目安","value":"未計測","note":"のぞみ基準の目安。列車や走行速度、天候・遮蔽物によって変わります"}},"name":"田丸屋のわさび漬看板","area":"静岡 → 掛川（静岡駅のすぐ西）","hook":"昼は緑、夜はネオン。","headingChunks":["静岡を知らせる、","緑の看板"],"heading":"静岡を知らせる、緑の看板","sectionHeading":"窓の外に、大きな「わさび漬」","story":"静岡駅の西側。E席の窓を追っていると、ビルの屋上に横長の緑色の看板が現れます。上には黄色い「田丸屋の」、下には白い「わさび漬」。駅名標を読まなくても、この色と文字で静岡を思い出す人がいるのではないでしょうか。\n\n一見すると大きな商品名ですが、その奥には、光を動かす職人の技と、鉄道に育てられた土地の味があります。昼の写真から夜の光を想像し、看板の文字から昔の駅の風景へ。通り過ぎる一枚を、少しゆっくり読んでみましょう。","minutes":53.25,"side":"E","sideLabel":"E席・山側","spotting":null,"facts":{"labels":["見える区間","座席側","タイミング","写真"],"timing":"東京発のぞみ基準で約53分後","photoUnit":"枚"},"photos":[{"src":"images/20261029_tamaruya-wasabi-sign_123500_michikusa.jpg","thumb":"images/thumbs/20261029_tamaruya-wasabi-sign_123500_michikusa.webp","alt":"田丸屋のわさび漬看板の新幹線車窓写真","note":"静岡通過直後のE席側（拡大）","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":"静岡通過直後のE席側（拡大）"},{"src":"images/20261029_tamaruya-wasabi-sign_context_123500_michikusa.jpg","thumb":"images/thumbs/20261029_tamaruya-wasabi-sign_context_123500_michikusa.webp","alt":"静岡駅の西側で、街並みの屋上に見える緑色の田丸屋のわさび漬看板","note":"周囲の街並みを含む車窓の全景","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":"周囲の街並みを含む車窓の全景"}],"hero":{"src":"images/20261029_tamaruya-wasabi-sign_123500_michikusa.jpg","thumb":"images/thumbs/20261029_tamaruya-wasabi-sign_123500_michikusa.webp","alt":"田丸屋のわさび漬看板の新幹線車窓写真","note":"静岡通過直後のE席側（拡大）","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":"静岡通過直後のE席側（拡大）"},"gallery":[{"src":"images/20261029_tamaruya-wasabi-sign_123500_michikusa.jpg","thumb":"images/thumbs/20261029_tamaruya-wasabi-sign_123500_michikusa.webp","alt":"田丸屋のわさび漬看板の新幹線車窓写真","note":"静岡通過直後のE席側（拡大）","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":"静岡通過直後のE席側（拡大）","smallThumb":"images/thumbs/gallery/20261029_tamaruya-wasabi-sign_123500_michikusa.webp"},{"src":"images/20261029_tamaruya-wasabi-sign_context_123500_michikusa.jpg","thumb":"images/thumbs/20261029_tamaruya-wasabi-sign_context_123500_michikusa.webp","alt":"静岡駅の西側で、街並みの屋上に見える緑色の田丸屋のわさび漬看板","note":"周囲の街並みを含む車窓の全景","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":"周囲の街並みを含む車窓の全景","smallThumb":"images/thumbs/gallery/20261029_tamaruya-wasabi-sign_context_123500_michikusa.webp"}],"photoHeading":"写真で見る田丸屋のわさび漬看板","photoHeadingCustom":false,"inline":[],"photoTip":null,"bodyLinks":[{"label":"田丸屋本店：歴史・沿革","href":"https://tamaruya.co.jp/history.html"},{"label":"田丸屋本店：商品案内・わさび漬","href":"https://www.tamaruya.co.jp/item.html"}],"routeNote":"","fujiGuide":null,"explainer":null,"referenceImage":null,"sharedGuide":[],"guideNotice":null,"map":{"hasCoordinates":true,"lat":34.967466,"lng":138.381149,"name":"田丸屋のわさび漬看板のある建物付近","externalUrl":"https://www.google.com/maps/search/?api=1&query=34.967466%2C138.381149","embedUrl":"https://www.google.com/maps/embed/v1/place?key=AIzaSyDE3UdN_9m9cK5sLTlfuc7KElsfceYNwrs&q=34.967466%2C138.381149&center=34.967466%2C138.381149&zoom=15&maptype=satellite&language=ja","viewpointUrl":"https://www.google.com/maps/embed/v1/place?key=AIzaSyDE3UdN_9m9cK5sLTlfuc7KElsfceYNwrs&q=34.966433%2C138.380956&center=34.967466%2C138.381149&zoom=15&maptype=satellite&language=ja","viewpoint":{"lat":34.966433,"lng":138.380956}},"guide":{"title":"田丸屋のわさび漬看板を見逃さないコツ","intro":"静岡 → 掛川（静岡駅のすぐ西）が近づいたら、E席・山側の窓を先に意識してください。現在地から追う場合は音声ガイド、事前に確認する場合はこのページの地図が役立ちます。","duration":"総可視時間は未計測です。列車や天候、遮蔽物によって変わるため、少し前から窓の外を追うと見つけやすくなります。","timingLead":"乗る列車が決まっているなら、列車選択で実際のダイヤに合わせた見える時刻を調べられます。","cta":"列車を選んで、見える時刻を調べる","href":"../start.html#journey","highlight":"新大阪方面は静岡駅のホームを抜けたらE席側へ。東京方面は静岡駅へ入る手前です。近くの建物の屋上にある、緑地と白い「わさび漬」の文字を探してください。"},"references":[{"label":"日本サイン協会：わたしは37才のネオン広告塔（アオイネオン・2025年）","href":"https://sign-jp.org/wasabiduke/"},{"label":"田丸屋本店：歴史・沿革","href":"https://www.tamaruya.co.jp/history.html"},{"label":"田丸屋本店：わさび漬の歴史","href":"https://www.tamaruya.co.jp/about.html"},{"label":"田丸屋本店：わさび漬の製造工程","href":"https://www.tamaruya.co.jp/factory.html"}],"related":[{"id":"fuji-pipe-sign","href":"fuji-pipe-sign.html","thumb":"images/thumbs/20260804_fujipipe_michikusa.webp","label":"関連","name":"フジパイプ","hook":"カラフルなフジパイプの屋上広告"},{"id":"genki-sign","href":"genki-sign.html","thumb":"images/thumbs/20260712_genki_sign_michikusa.webp","label":"関連","name":"しっぺいの応援看板","hook":"元気が出る、しっぺいの三連看板。"},{"id":"toyohashi-tateiwa","href":"toyohashi-tateiwa.html","thumb":"images/thumbs/20210923_toyohashi_tateiwa_pato727.webp","label":"関連","name":"豊橋の立岩","hook":"浜名湖のあと、岩が立つ。"}],"media":null,"showcase":false,"stamp":{"src":"images/stamps/stamp_tamaruya-wasabi-sign.svg","label":"車窓スタンプ","alt":"田丸屋のわさび漬看板の車窓スタンプ"},"chapters":[{"id":"read-the-sign","heading":"緑、黄色、白。｜色から読む静岡","paragraphs":["写真を見ると、背景は細い縦の線が集まった緑色。その上に黄色い屋号、下に大きな白い商品名が重なっています。小さな商品写真や長い説明よりも、色の面と太い文字が前に出る構成です。動く列車の中では、まず緑のかたまりを見つけ、次に「わさび漬」を読む、という探し方ができます。","「田丸屋」は店の名前、「わさび漬」は食べものの名前。読み方は、たまるや・わさびづけです。看板の言葉を分けてみると、遠くからでも伝えたい二つの情報が見えてきます。静岡の駅を通り過ぎる短い時間に、店と名物を一緒に覚えてもらう看板として眺めてみてください。"],"photos":[{"src":"images/20261029_tamaruya-wasabi-sign_123500_michikusa.jpg","thumb":"images/thumbs/20261029_tamaruya-wasabi-sign_123500_michikusa.webp","alt":"田丸屋のわさび漬看板の新幹線車窓写真","note":"緑の縦線に重なる、黄色い屋号と白い商品名。","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":"緑の縦線に重なる、黄色い屋号と白い商品名。"}],"kind":"background"},{"id":"neon","heading":"約500mの管が、｜夜の光をつくる","paragraphs":["設計製作を手がけたアオイネオンの担当者による2025年の解説では、設置は1988年9月。看板の大きさは高さ5m、幅9.45mで、約500mのネオン管を49台の変圧器で点灯させています。屋上の一枚に、見た目からは想像しにくい長さの光の管が詰まっているのです。","文字は点灯を保ち、背景の緑色は32段の点滅器で順に流れるように動いた後、全体が消えて一斉に点く仕組み。昼の写真で見える縦線は、夜には時間を持った模様になります。静止画だけでは分からないところまで知ると、次に夜の窓から探す楽しみが増えます。","同じ解説には、1988年の手描き配線図を保存し、当時の仕様を確かめながら手入れしていることも記されています。今見える光の背景には、設計図を残し、屋外の設備を守る仕事があります。"],"photos":[],"link":{"route":"https://sign-jp.org/wasabiduke/","label":"製作会社が語るネオンと、当時の配線図を見る ↗"},"kind":"background"},{"id":"railway-food","heading":"静岡駅とつながる、｜わさび漬の味","paragraphs":["田丸屋の名前が鉄道と結びついたのは、新幹線よりずっと前です。公式沿革では、1890年の駅前への移転と、駅弁に添えたわさび漬の好評が紹介されています。公式の歴史解説には、木の化粧樽に詰め、列車の窓から旅人へ売った販売風景も登場します。","かつては、窓の向こうの売り手から土地の味を受け取った。その後は車内販売にも載り、今の窓には大きな商品名が見える。買う場所や旅の速さは変わっても、静岡を通る人へ名物を届けようとするつながりを、この看板からたどれます。"],"photos":[],"link":{"route":"https://www.tamaruya.co.jp/history.html","label":"田丸屋の沿革で、鉄道との歩みをたどる ↗"},"kind":"background","records":[{"year":"1875年","title":"漬物屋として創業","text":"静岡市新通りで、佃煮と漬物の製造販売を始めました。"},{"year":"1895年","title":"静岡駅ホームの立ち売りへ","text":"公式沿革に、ホームで売る許可を得た年として記されています。"},{"year":"1902年","title":"平たい樽を考案","text":"わさび漬を入れる平樽を発売。中身だけでなく、旅へ持ち帰る容器にも工夫がありました。"},{"year":"1964年","title":"新幹線の旅にも","text":"東海道新幹線の開業に合わせ、車内販売への納品が始まります。"}]},{"id":"wasabi-zuke","heading":"すりおろすだけではない、｜わさびの食べ方","paragraphs":["わさび漬は、寿司に添える緑の薬味とは姿の違う食べものです。田丸屋の製造工程では、根と茎を使い、洗浄・細断・塩漬けを経て、酒粕や調味料と練り合わせます。酒粕は日本酒造りで生まれる材料。わさびの辛みと、発酵から生まれる香りを合わせた漬物です。","公式の歴史解説では、安倍川上流で食べられていた茎の漬物から、酒粕を使うわさび漬へ発展したと伝えています。根をすりおろす食べ方だけでなく、茎も使って味わう。看板の「漬」という一字に目を留めると、普段知っているわさびから、静岡の食卓へ少し近づけます。"],"photos":[],"link":{"route":"https://www.tamaruya.co.jp/factory.html","label":"根と茎が、わさび漬になる工程を見る ↗"},"kind":"background"},{"id":"spotting","heading":"静岡駅の西側で、｜E席の窓へ","paragraphs":["東京から新大阪へ向かうときは、静岡駅のホームを抜けた後のE席側。東京へ向かうときは、静岡駅に入る前のE席側です。看板は駅の西側にあり、田丸屋本店の店舗そのものを示す目印ではありません。","下の広めの車窓写真では、看板が街並みのどの高さに出るかを確かめられます。近い建物や架線柱が重なるので、正面から全ての文字を読むことにこだわらず、屋根より上の緑色を探してみてください。昼に形を覚えておけば、夜の通過では、その形に光が入った姿を探せます。"],"photos":[{"src":"images/20261029_tamaruya-wasabi-sign_context_123500_michikusa.jpg","thumb":"images/thumbs/20261029_tamaruya-wasabi-sign_context_123500_michikusa.webp","alt":"静岡駅の西側で、街並みの屋上に見える緑色の田丸屋のわさび漬看板","note":"街並みを含めた車窓。屋根の上の緑色が、見つける高さの手がかり。","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":"街並みを含めた車窓。屋根の上の緑色が、見つける高さの手がかり。"}],"kind":"background"}],"imageSources":{"images/20261029_tamaruya-wasabi-sign_123500_michikusa.jpg":[["images/thumbs/display/20261029_tamaruya-wasabi-sign_123500_michikusa-4e4f308a-640.webp",640,360],["images/thumbs/20261029_tamaruya-wasabi-sign_123500_michikusa.webp",800,450]],"images/20261029_tamaruya-wasabi-sign_context_123500_michikusa.jpg":[["images/thumbs/display/20261029_tamaruya-wasabi-sign_context_123500_michikusa-5302357f-640.webp",640,360],["images/thumbs/20261029_tamaruya-wasabi-sign_context_123500_michikusa.webp",960,540],["images/thumbs/display/20261029_tamaruya-wasabi-sign_context_123500_michikusa-5302357f-1920.webp",1920,1080]]}};
}(typeof window !== "undefined" ? window : globalThis));
